    this.startupTimeoutMs = options.startupTimeoutMs ?? 20_000;
    this.prepareTimeoutMs = options.prepareTimeoutMs ?? 1000;
    this.maxRestarts = options.maxRestarts ?? 3;
    this.restartWindowMs = options.restartWindowMs ?? 60_000;
