    public func shutdown() {
        lock.withLock {
            recording = false
            shuttingDown = true
        }
        let finished = DispatchSemaphore(value: 0)
        queue.async { [self] in
            resume(afterEpoch: nil, shuttingDown: true)
            finished.signal()
        }
        _ = finished.wait(timeout: .now() + timing.shutdownBudget)
