    // MARK: - Pause

    private func pauseIfPlaying(epoch mine: Int) {
        guard !unsupported, isEnabled() else { return }
        // Already holding it: a back-to-back dictation. Keep it paused, pause nothing twice.
        guard hold == nil else { return }
